// src/client.ts
import { z as z2 } from "zod/v4";

// src/lib/browser-storage.ts
var TOKEN_KEY = "runable.managed-auth.token";
var NONCE_KEY = "runable.managed-auth.nonce";

class BrowserStorage {
  getToken() {
    return localStorage.getItem(TOKEN_KEY) ?? "";
  }
  setToken(token) {
    localStorage.setItem(TOKEN_KEY, token);
  }
  clearToken() {
    localStorage.removeItem(TOKEN_KEY);
  }
  setNonce(nonce) {
    sessionStorage.setItem(NONCE_KEY, nonce);
  }
  takeNonce() {
    const nonce = sessionStorage.getItem(NONCE_KEY);
    sessionStorage.removeItem(NONCE_KEY);
    return nonce ?? undefined;
  }
}
var browserStorage = new BrowserStorage;

// src/lib/exchange.ts
import { z } from "zod/v4";
var exchangeResponseSchema = z.object({ data: z.object({ token: z.string() }) });
var exchangeToken = async ($fetch, input) => {
  const body = { token: input.token };
  if (input.codeVerifier)
    body.codeVerifier = input.codeVerifier;
  const response = await $fetch("/managed/exchange", { method: "POST", body });
  const result = exchangeResponseSchema.safeParse(response);
  if (!result.success)
    throw new Error("Managed auth exchange failed");
  return result.data.data.token;
};
var completeExchange = async ({ $fetch, storage }, input) => {
  try {
    storage.setToken(await exchangeToken($fetch, input));
    return { data: { success: true }, error: null };
  } catch {
    return {
      data: null,
      error: { code: "EXCHANGE_FAILED", message: "Managed auth exchange failed" }
    };
  }
};

// src/lib/fragment.ts
var parseFragment = (input) => {
  const hashIndex = input.indexOf("#");
  if (hashIndex === -1)
    return;
  const params = new URLSearchParams(input.slice(hashIndex + 1));
  const nonce = params.get("nonce");
  const token = params.get("token");
  const error = params.get("error");
  if (!nonce)
    return;
  if (token)
    return { nonce, token };
  if (error)
    return { nonce, error, errorDescription: params.get("error_description") ?? undefined };
  return;
};
var providerErrorResult = (fragment) => ({
  data: null,
  error: { code: fragment.error, message: fragment.errorDescription ?? fragment.error }
});

// src/lib/pkce.ts
class Pkce {
  static CLAIM = "pkce_s256";
  static base64url(bytes) {
    const binary = Array.from(bytes, (byte) => String.fromCharCode(byte)).join("");
    return Pkce.fromBase64(btoa(binary));
  }
  static fromBase64(base64) {
    const unpadded = base64.replaceAll("+", "-").replaceAll("/", "_");
    const padIndex = unpadded.indexOf("=");
    return padIndex === -1 ? unpadded : unpadded.slice(0, padIndex);
  }
  static randomToken() {
    const bytes = new Uint8Array(32);
    crypto.getRandomValues(bytes);
    return Pkce.base64url(bytes);
  }
  static async challengeS256(verifier) {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
    return Pkce.base64url(new Uint8Array(digest));
  }
}

// src/lib/scheme.ts
var applicationScheme = (applicationId) => `runable-${applicationId}`;

// src/lib/start-url.ts
var buildStartUrl = (options) => {
  const issuer = options.issuer.endsWith("/") ? options.issuer.slice(0, -1) : options.issuer;
  const url = new URL(`${issuer}/managed/start`);
  const params = new URLSearchParams({
    application_id: options.applicationId,
    provider: options.provider,
    origin: options.redirectTarget,
    nonce: options.nonce
  });
  if (options.codeChallenge)
    params.set("code_challenge", options.codeChallenge);
  url.search = params.toString();
  return url.toString();
};

// src/lib/desktop-flow.ts
var getDesktopBridge = () => globalThis.managedAuth;
var DEEP_LINK_TIMEOUT_MS = 5 * 60 * 1000;
var waitForDeepLink = (bridge, nonce) => new Promise((resolve) => {
  const settle = (fragment) => {
    unsubscribe();
    clearTimeout(timeout);
    resolve(fragment);
  };
  const unsubscribe = bridge.onDeepLink((url) => {
    const fragment = parseFragment(url);
    if (fragment && fragment.nonce === nonce)
      settle(fragment);
  });
  const timeout = setTimeout(() => settle(undefined), DEEP_LINK_TIMEOUT_MS);
});
var desktopSignIn = async ({ config, bridge, ...context }, options) => {
  const nonce = Pkce.randomToken();
  const codeVerifier = Pkce.randomToken();
  const redirectTarget = config.redirectTarget ?? await bridge.getRedirectTarget?.() ?? `${applicationScheme(config.applicationId)}://auth/callback`;
  const url = buildStartUrl({
    issuer: config.issuer,
    applicationId: config.applicationId,
    provider: options.provider,
    redirectTarget,
    nonce,
    codeChallenge: await Pkce.challengeS256(codeVerifier)
  });
  await bridge.openExternal(url);
  const fragment = await waitForDeepLink(bridge, nonce);
  if (!fragment) {
    return { data: null, error: { code: "DEEP_LINK_TIMEOUT", message: "Sign-in timed out" } };
  }
  if ("error" in fragment)
    return providerErrorResult(fragment);
  return completeExchange(context, { token: fragment.token, codeVerifier });
};

// src/lib/bearer.ts
var bearerFetchPlugin = (store) => ({
  id: "runable-managed-auth-bearer",
  name: "Runable Managed Auth Bearer",
  hooks: {
    onRequest(context) {
      const token = store.getToken();
      if (!token)
        return context;
      const headers = new Headers(context.headers);
      if (!headers.has("authorization"))
        headers.set("authorization", `Bearer ${token}`);
      return { ...context, headers };
    },
    onSuccess(context) {
      if (new URL(context.request.url).pathname.endsWith("/sign-out"))
        store.clearToken();
    }
  }
});

// src/lib/plugin.ts
var managedAuthPlugin = (storage, createFlows) => ({
  id: "runable-managed-auth",
  fetchPlugins: [bearerFetchPlugin(storage)],
  getActions: ($fetch, $store) => {
    const flows = createFlows({ $fetch, storage });
    const refreshed = async (result) => {
      if (result?.data?.success) {
        await $fetch("/get-session");
        $store.notify("$sessionSignal");
      }
      return result;
    };
    return {
      managedAuth: {
        signIn: async (options) => refreshed(await flows.signIn(options)),
        handleRedirect: async () => refreshed(await flows.handleRedirect()),
        getToken: () => storage.getToken(),
        clearToken: () => storage.clearToken()
      }
    };
  }
});

// src/client.ts
var MESSAGE_TYPE = "runable-managed-auth";
var POPUP_TIMEOUT_MS = 5 * 60 * 1000;
var popupMessageSchema = z2.object({
  type: z2.literal(MESSAGE_TYPE),
  nonce: z2.string(),
  token: z2.string().optional(),
  error: z2.string().optional(),
  error_description: z2.string().optional()
}).refine((data) => data.token !== undefined || data.error !== undefined, {
  message: "popup message must carry a token or an error"
});
var isEmbedded = () => {
  if (typeof window === "undefined" || window.self === window.top)
    return false;
  try {
    return typeof window.top?.location.href !== "string";
  } catch {
    return true;
  }
};
var stripFragment = () => {
  history.replaceState(null, "", window.location.pathname + window.location.search);
};
var popupFeatures = () => {
  const width = 500;
  const height = 600;
  const left = window.screenX + (window.outerWidth - width) / 2;
  const top = window.screenY + (window.outerHeight - height) / 2;
  return `width=${width},height=${height},left=${left},top=${top},menubar=no,toolbar=no`;
};
var waitForPopup = (popup, nonce) => new Promise((resolve) => {
  const settle = (outcome) => {
    window.removeEventListener("message", onMessage);
    clearInterval(closedPoll);
    clearTimeout(timeout);
    if (!popup.closed)
      popup.close();
    resolve(outcome);
  };
  const onMessage = (event) => {
    if (event.origin !== window.location.origin)
      return;
    const message = popupMessageSchema.safeParse(event.data);
    if (!message.success || message.data.nonce !== nonce)
      return;
    if (message.data.token) {
      settle({ token: message.data.token });
    } else if (message.data.error) {
      settle({
        error: {
          code: message.data.error,
          message: message.data.error_description ?? message.data.error
        }
      });
    }
  };
  const closedPoll = setInterval(() => {
    if (popup.closed)
      settle({ error: { code: "POPUP_CLOSED", message: "Popup closed" } });
  }, 500);
  const timeout = setTimeout(() => settle({ error: { code: "POPUP_TIMEOUT", message: "Popup timed out" } }), POPUP_TIMEOUT_MS);
  window.addEventListener("message", onMessage);
});
var webSignIn = async (context, options) => {
  const nonce = Pkce.randomToken();
  const url = buildStartUrl({
    issuer: context.config.issuer,
    applicationId: context.config.applicationId,
    provider: options.provider,
    redirectTarget: window.location.origin,
    nonce
  });
  if (!isEmbedded()) {
    browserStorage.setNonce(nonce);
    window.location.href = url;
    return { data: null, error: null };
  }
  const popup = window.open(url, MESSAGE_TYPE, popupFeatures());
  if (!popup)
    return { data: null, error: { code: "POPUP_BLOCKED", message: "Popup blocked" } };
  const outcome = await waitForPopup(popup, nonce);
  if ("error" in outcome)
    return { data: null, error: outcome.error };
  return completeExchange(context, { token: outcome.token });
};
var webHandleRedirect = async (context) => {
  const fragment = parseFragment(window.location.hash);
  if (!fragment)
    return;
  if (window.name === MESSAGE_TYPE && window.opener) {
    const message = "error" in fragment ? {
      type: MESSAGE_TYPE,
      nonce: fragment.nonce,
      error: fragment.error,
      error_description: fragment.errorDescription
    } : { type: MESSAGE_TYPE, nonce: fragment.nonce, token: fragment.token };
    window.opener.postMessage(message, window.location.origin);
    stripFragment();
    window.close();
    return;
  }
  const expectedNonce = browserStorage.takeNonce();
  stripFragment();
  if (!expectedNonce || expectedNonce !== fragment.nonce)
    return;
  if ("error" in fragment)
    return providerErrorResult(fragment);
  return completeExchange(context, { token: fragment.token });
};
var managedAuthClient = (config) => managedAuthPlugin(browserStorage, (context) => ({
  signIn: (options) => {
    const bridge = getDesktopBridge();
    return bridge ? desktopSignIn({ ...context, config, bridge }, options) : webSignIn({ ...context, config }, options);
  },
  handleRedirect: async () => getDesktopBridge() ? undefined : webHandleRedirect({ ...context, config })
}));
export {
  webSignIn,
  webHandleRedirect,
  managedAuthClient
};
